diff --git a/src/policy.mjs b/src/policy.mjs
index 5fe60c7..6347298 100644
--- a/src/policy.mjs
+++ b/src/policy.mjs
@@ -1,3 +1,8 @@
 export function shouldRetry(error, completedAttempts, maxAttempts) {
-  return completedAttempts < maxAttempts;
+  if (error?.name === "AbortError" || completedAttempts >= maxAttempts) {
+    return false;
+  }
+
+  const status = error?.status;
+  return status === 429 || (status >= 500 && status < 600);
 }

