diff --git a/src/redirect.mjs b/src/redirect.mjs
index 75eb695..9f57a58 100644
--- a/src/redirect.mjs
+++ b/src/redirect.mjs
@@ -1,3 +1,12 @@
 export function isSafeRedirect(location, baseUrl) {
-  return location.startsWith("/");
+  try {
+    const base = new URL(baseUrl);
+    const destination = new URL(location, base);
+    return (
+      (destination.protocol === "http:" || destination.protocol === "https:") &&
+      destination.origin === base.origin
+    );
+  } catch {
+    return false;
+  }
 }

